  'suggest_bank_matches': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"limit":{"default":null,"description":"Maximum candidates to return, default 5.","format":"int64","type":["integer","null"]},"txn_id":{"description":"Id of the bank transaction.","format":"int32","type":"integer"}},"required":["txn_id"],"title":"SuggestBankMatchesInput","type":"object"},
